import { test, expect } from '@playwright/test';

test.describe('File Upload - Remove File from Queue', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully remove a file from the upload queue and proceed with submission', async ({ page }) => {
    // Verify upload queue is empty initially
    const uploadQueueCount = page.getByRole('heading', { name: /upload queue/i }).count();
    expect(uploadQueueCount).toBe(0);

    // Upload a file
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('fixtures/sample-file.pdf');

    // Verify file appears in queue
    const fileList = page.getByRole('list', { name: /upload queue/i });
    await expect(fileList).toBeVisible();
    const fileItem = page.getByText('sample-file.pdf');
    await expect(fileItem).toBeVisible();

    // Verify file is selected
    const fileSelect = page.getByRole('button', { name: /select/i });
    await expect(fileSelect).toBeVisible();
    await fileSelect.click();

    // Verify file is highlighted
    await expect(fileItem).toBeVisible();

    // Remove file from queue
    const removeButton = page.getByRole('button', { name: /remove/i });
    await removeButton.click();

    // Verify file is removed
    await expect(fileItem).not.toBeVisible();
    const uploadQueueCountAfterRemove = page.getByRole('heading', { name: /upload queue/i }).count();
    expect(uploadQueueCountAfterRemove).toBe(0);

    // Submit remaining files
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message
    const successMessage = page.getByText(/files submitted successfully/i);
    await expect(successMessage).toBeVisible();
  });

  test('should display error when trying to remove a non-existent file from the queue', async ({ page }) => {
    // Upload a file
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('fixtures/sample-file.pdf');

    // Verify file appears in queue
    const fileList = page.getByRole('list', { name: /upload queue/i });
    await expect(fileList).toBeVisible();
    const fileItem = page.getByText('sample-file.pdf');
    await expect(fileItem).toBeVisible();

    // Remove non-existent file
    const removeButton = page.getByRole('button', { name: /remove/i });
    await removeButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/file not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify file is still in queue
    await expect(fileItem).toBeVisible();

    // Verify submit button is still available
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();
  });
});
